mapper.select:
SELECT i.id, i.title, i.content, i.category, i.status, i.priority, i.author_id, i.assignee_id, i.organization_id, i.folder_id, i.created_at, i.updated_at, u1.username AS author_name, u1.email AS author_email, u2.username AS assignee_name, u2.email AS assignee_email FROM issues i LEFT JOIN users u1 ON i.author_id = u1.id LEFT JOIN users u2 ON i.assignee_id = u2.id
AND i.status = #{status}
AND i.category = #{category}
AND i.priority = #{priority}
AND i.assignee_id = #{assigneeId}
AND i.author_id = #{authorId}
AND i.folder_id = #{folderId}
AND (i.title ILIKE '%' || #{keyword} || '%' OR i.content ILIKE '%' || #{keyword} || '%')
ORDER BY
CASE i.priority WHEN 'CRITICAL' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 4 END, i.created_at DESC, i.id DESC
i.status, i.created_at DESC, i.id DESC
i.created_at DESC, i.id DESC
LIMIT #{limit}
OFFSET #{offset}

